        code: '// Bed Wars: every team has a bed. While your bed stands, you come back at your team\'s spawn after dying. Break the\n// other teams\' beds (not your own!) so they can\'t come back, then knock them out. The last team left wins.\nconst bedsStanding = {}\nlet generatorTimer = null\n\nfunction onPlayerJoin(playerId) {\n\tjoinSmallestTeam(playerId)\n\tif (isRoundRunning()) {\n\t\teliminate(playerId)\n\t\tapi.sendMessage(playerId, "A round is on: watch this one, you\'ll play in the next!", { color: "yellow" })\n\t\treturn\n\t}\n\tapi.setPlayerGamemode(playerId, "survival")\n\tsendToSpawn(playerId)\n\tapi.sendMessage(playerId, "Welcome to Bed Wars! Protect your bed and break the others.", { color: "aqua" })\n}\n\nfunction teamSpawn(team) {\n\treturn CONFIG.teamSpawns[CONFIG.teamNames.indexOf(team)] || CONFIG.teamSpawns[0]\n}\n\nfunction teamBed(team) {\n\tconst bed = CONFIG.bedPositions[CONFIG.teamNames.indexOf(team)] || CONFIG.bedPositions[0]\n\treturn [Math.floor(bed[0]), Math.floor(bed[1]), Math.floor(bed[2])]\n}\n\nfunction sendToSpawn(playerId) {\n\tconst spot = teamSpawn(getTeam(playerId))\n\tapi.setPosition(playerId, spot[0], spot[1], spot[2])\n}\n\nfunction beginRound() {\n\tbringEveryoneBack()\n\tevenTeams()\n\tCONFIG.teamNames.forEach((team, index) => {\n\t\tconst bed = teamBed(team)\n\t\tbedsStanding[team] = teamMembers(team).length > 0\n\t\tif (bedsStanding[team]) {\n\t\t\tapi.setBlock(bed[0], bed[1], bed[2], CONFIG.bedBlocks[index] || CONFIG.bedBlocks[0])\n\t\t}\n\t})\n\tfor (const playerId of api.getPlayerIds()) {\n\t\tif (!api.isAlive(playerId)) {\n\t\t\tapi.forceRespawn(playerId, teamSpawn(getTeam(playerId)))\n\t\t}\n\t\tsendToSpawn(playerId)\n\t\thealFully(playerId)\n\t\tgiveKit(playerId, CONFIG.startItems)\n\t}\n\tgeneratorTimer = repeatEvery(CONFIG.generatorSeconds, runGenerators)\n\tannounce("Protect your bed and break the others!", "aqua")\n}\n\n// After players leave, one team can be much bigger: move players from the biggest team until the teams are even\nfunction evenTeams() {\n\tfor (let i = 0; i < api.getPlayerIds().length; i++) {\n\t\tconst sizes = CONFIG.teamNames.map((team) => teamMembers(team).length)\n\t\tif (Math.max(...sizes) - Math.min(...sizes) <= 1) {\n\t\t\treturn\n\t\t}\n\t\tconst biggest = CONFIG.teamNames[sizes.indexOf(Math.max(...sizes))]\n\t\tjoinSmallestTeam(teamMembers(biggest)[0])\n\t}\n}\n\nfunction finishRound() {\n\tcancelTimer(generatorTimer)\n\t// Those knocked out play again, waiting at their spawn for the next round\n\tconst left = playersLeft()\n\tconst out = api.getPlayerIds().filter((playerId) => !left.includes(playerId))\n\tbringEveryoneBack()\n\tfor (const playerId of out) {\n\t\tif (api.isAlive(playerId)) {\n\t\t\tsendToSpawn(playerId)\n\t\t}\n\t}\n}\n\n// Gives every player still in the round their team generator\'s items\nfunction runGenerators() {\n\tfor (const playerId of playersLeft()) {\n\t\tif (getTeam(playerId) !== null && api.isAlive(playerId)) {\n\t\t\tapi.giveItem(playerId, CONFIG.resourceItem, CONFIG.resourceAmount)\n\t\t}\n\t}\n}\n\n// The team whose bed is at (or right next to) x, y, z, or null\nfunction bedOwnerAt(x, y, z) {\n\tfor (const team of CONFIG.teamNames) {\n\t\tconst bed = teamBed(team)\n\t\tif (Math.abs(x - bed[0]) <= 1 && y === bed[1] && Math.abs(z - bed[2]) <= 1) {\n\t\t\treturn team\n\t\t}\n\t}\n\treturn null\n}\n\n// A bed\'s foot ("Red Bed") or head ("_Red Bed Head"), not Bedrock\nfunction isBedBlock(block) {\n\treturn / Bed( Head)?$/.test(block)\n}\n\nfunction onPlayerAttemptChangeBlock(playerId, x, y, z, fromBlock, toBlock) {\n\tconst team = isBedBlock(fromBlock) ? bedOwnerAt(x, y, z) : null\n\tif (team === null) {\n\t\treturn\n\t}\n\tif (!isRoundRunning()) {\n\t\treturn "preventChange"\n\t}\n\tif (team === getTeam(playerId)) {\n\t\tapi.sendMessage(playerId, "That\'s your own bed! Protect it.", { color: "red" })\n\t\treturn "preventChange"\n\t}\n}\n\nfunction onPlayerChangeBlock(playerId, x, y, z, fromBlock, toBlock) {\n\tconst team = isBedBlock(fromBlock) ? bedOwnerAt(x, y, z) : null\n\tif (team !== null && bedsStanding[team] && isRoundRunning()) {\n\t\tbedsStanding[team] = false\n\t\tannounce(api.getEntityName(playerId) + " broke team " + team + "\'s bed!", "red")\n\t\tfor (const member of teamMembers(team)) {\n\t\t\tapi.sendMessage(member, "Your bed is gone! If you die now, you\'re out.", { color: "red" })\n\t\t}\n\t}\n}\n\nfunction onPlayerDamagingOtherPlayer(attackingPlayer, damagedPlayer) {\n\t// Falls, and spikes or lava whose placer isn\'t in the game, come in as a player hurting themselves\n\tif (!isRoundRunning() || (attackingPlayer !== damagedPlayer && sameTeam(attackingPlayer, damagedPlayer))) {\n\t\treturn "preventDamage"\n\t}\n}\n\nfunction onRespawnRequest(playerId) {\n\tif (isRoundRunning() && playersLeft().includes(playerId)) {\n\t\trunLater(0.5, () => {\n\t\t\tgiveKit(playerId, CONFIG.startItems)\n\t\t})\n\t}\n\treturn teamSpawn(getTeam(playerId))\n}\n\nfunction tick(ms) {\n\tif (!isRoundRunning()) {\n\t\treturn\n\t}\n\t// A player who died with their bed gone is out\n\tfor (const playerId of playersLeft()) {\n\t\tif (!api.isAlive(playerId) && !bedsStanding[getTeam(playerId)]) {\n\t\t\teliminate(playerId)\n\t\t\tannounce(api.getEntityName(playerId) + " is out!", "red")\n\t\t}\n\t}\n\t// Players leaving or being knocked out can leave one team\n\tconst teamsLeft = []\n\tfor (const playerId of playersLeft()) {\n\t\tconst team = getTeam(playerId)\n\t\tif (team !== null && !teamsLeft.includes(team)) {\n\t\t\tteamsLeft.push(team)\n\t\t}\n\t}\n\tif (teamsLeft.length === 1) {\n\t\tteamWins(teamsLeft[0])\n\t} else if (teamsLeft.length === 0) {\n\t\tendRound("Nobody is left! Nobody wins.")\n\t}\n}\n\nfunction teamWins(team) {\n\tendRound("Team " + team + " wins!")\n}',
